from author import C,S,R,P,T
c=C('中值定理与洛必达法则')
S(c,'罗尔定理：三条件与一个结论',[R('闭区间连续、开区间可导、端点值相等','f\\in C[a,b],\\quad f(a)=f(b)'),R('结论',r"\exists\xi\in(a,b):\ f'(\xi)=0"),R('例题',r"f(x)=x^2-x,\quad[a,b]=[0,1]"),R('求中间点',r"2\xi-1=0\quad\Longrightarrow\quad\xi=\frac12")],[P('微分中值定理的基础题，先核对条件，再套结论。罗尔定理要闭区间连续、开区间可导、两端函数值相等，才能保证内部有一点导数为零。考试要求说明定理适用时，把这三条逐项写清楚。只看到两端相等，不能忽略函数中间是否存在断点或不可导点。',[1,2],['闭区间连续、开区间可导','还需要两端函数值相等']),P('例题x平方减x在零到一是多项式，连续可导，两个端点都为零，符合条件。把导数二x减一设为零，解得中间点二分之一，并检查它确实在开区间内。定理中的点不是端点，所以算出一个数字以后，还要确认它落在题目指定的内部范围。',[3,4],['先交代条件，再解导数为零','求出的点必须位于开区间'])],['微分中值定理'])
S(c,'拉格朗日与柯西：认准差商',[R('拉格朗日',r"f'(\xi)=\frac{f(b)-f(a)}{b-a},\quad\xi\in(a,b)"),R('例题',r"f(x)=x^2,\quad[a,b]=[0,2]"),R('计算',r"2\xi=\frac{4-0}{2-0}=2\quad\Longrightarrow\quad\xi=1"),R('柯西',r"\frac{f(b)-f(a)}{g(b)-g(a)}=\frac{f'(\xi)}{g'(\xi)}")],[P('拉格朗日定理不要求两端函数值相等，仍需闭区间连续、开区间可导。结论是某个内部点的导数，等于端点函数值之差除以端点自变量之差。例题x平方在零到二，右边算出二，所以令二ξ等于二，得到ξ等于一。这个题型就是算差商、求导、解出内部点。',[1,2,3],['拉格朗日不要求端点值相等','差商分母为b减a']),P('柯西定理把分母的自变量差换成另一个函数g的函数值差。标准比例形式要求f、g在闭区间连续、开区间可导，并保证g撇在内部不为零。看到两个函数的增量比，可优先考虑它。不要把分子分母各自套定理后，误以为得到的两个中间点必然就是同一个点。',[4],['比例形式注意g撇不能为零','两个函数由同一个内部点联系'])],['微分中值定理'])
S(c,'洛必达：先检查能不能用',[R('优先检查未定式','\\frac{0}{0},\\quad\\frac{\\infty}{\\infty}'),R('满足条件后',r"\lim\frac{f(x)}{g(x)}=\lim\frac{f'(x)}{g'(x)}"),R('例题',r"\lim_{x\to0}\frac{e^x-1-x}{x^2}"),R('第一遍',r"\lim_{x\to0}\frac{e^x-1}{2x}"),R('第二遍',r"\lim_{x\to0}\frac{e^x}{2}=\frac12")],[P('洛必达适用于零比零或无穷比无穷的商，还要有相应邻域内可导、分母导数不为零，以及求导后的商极限存在等条件。它的操作是分子单独求导，分母单独求导，再算商的极限，绝不是对整个分式使用商求导公式。第一步一定先把原式形式检查出来。',[1,2],['先确认零比零或无穷比无穷','分子分母分别求导']),P('例题分子分母都趋于零，第一遍得到e的x次方减一，除以二x，仍是零比零。重新检查后再用一次，得到e的x次方除以二，极限二分之一。每用一遍都重新判型，不能无论变成什么都继续求导。若求导后的比值没有极限，也不能反推原极限一定不存在。',[3,4,5],['每次使用前都重新判型','本题两次以后得到二分之一'])],['洛必达法则'])
S(c,'其他未定式：先变成可用的商',[R('例题',r"\lim_{x\to0^+}x\ln x"),R('改写为商',r"\lim_{x\to0^+}\frac{\ln x}{1/x}"),R('洛必达后',r"\lim_{x\to0^+}\frac{1/x}{-1/x^2}=\lim_{x\to0^+}(-x)=0"),R('幂的未定式先取对数',r"y=x^x\quad\Longrightarrow\quad\ln y=x\ln x\to0,\quad y\to1")],[P('零乘无穷不能直接用洛必达，先改成商。x乘自然对数x，可以把x移到分母成为一除以x，于是分子趋于负无穷，分母趋于正无穷。分别求导后是一除以x，除以负的一除以x平方，化成负x，结果零。题目中的右极限也不能漏，因为实数自然对数要求x为正。',[1,2,3],['乘积先改写成商','ln x在这里只从零右侧趋近']),P('遇到零的零次方、一的无穷次方这类幂未定式，可以先令y等于原式，再取对数，把它变成乘积，随后转成商处理。比如x趋于零右侧时，x的x次方取对数就是x乘ln x，刚算出极限零，所以原式趋于e的零次方，也就是一。最后别忘了从对数结果还原回原函数。',[4],['取对数后最后要还原','本题x的x次方趋于一'])],['洛必达法则','第二类重要极限'])
S(c,'洛必达练习',[R('计算',r"\lim_{x\to+\infty}\frac{\ln x}{x}")],[P('暂停做一道无穷远处的极限：自然对数x除以x。先说明这是哪一种未定式，再分别对分子和分母求导，最后取极限。不要把分母原来的x原封不动留下，也不要对整个商使用商求导法则，洛必达在这里处理的是两个导数的比值。',[1],['先判型，再分别求导','答案在下一页'])],['洛必达法则'],kind='question')
S(c,'洛必达练习答案',[R('无穷比无穷',r"\lim_{x\to+\infty}\frac{\ln x}{x}"),R('分别求导',r"\lim_{x\to+\infty}\frac{1/x}{1}=0")],[P('原式是无穷比无穷，条件满足。分子求导一除以x，分母求导一，最后极限为零。这里自然对数确实也趋于无穷，但不能因此认为两者比值必为一。是否都变大只是判型信息，真正的比值结果还要计算，不能用“都是无穷”代替这一行求导。',[1,2],['原式结果为零','两个量都无穷不表示比值为一'])],['洛必达法则'],kind='answer')

c=C('导数应用与渐近线')
S(c,'单调区间：按关键点分段验号',[R('例题与导数',r"f(x)=x^3-3x,\quad f'(x)=3(x-1)(x+1)"),R('分段点',r"x=-1,\quad x=1"),R('导数符号',r"(-\infty,-1):+;\quad(-1,1):-;\quad(1,+\infty):+"),R('对应结论',r"f'(x)>0:\nearrow,\qquad f'(x)<0:\searrow")],[P('求单调区间，先写定义域，再求导，再找导数为零或不存在的关键点，用它们把定义域切成若干段。每段取一个方便的数判断导数正负，正就递增，负就递减。定义域断开的点即使不是驻点，也必须断开区间，不能隔着函数没有定义的位置连成一段。',[1,2],['定义域是第一步','驻点、不可导点与断点都可能分段']),P('例题导数分解成三乘x减一乘x加一，关键点负一和一。三段符号依次正、负、正，因此两个外侧区间递增，中间递减。答案写区间，别只交出两个关键点。验号时可以选负二、零、二，把符号表写在草稿上，比凭图形印象判断更稳。',[3,4],['按负二、零、二分别验号','最终写出递增递减区间'])],['单调区间'])
S(c,'极值第一判别法：看左右变号',[T('先确认点处连续，再查候选位置',"f'(a)=0，或 f'(a) 不存在"),T('第一判别法','+ → −：极大值；− → +：极小值'),R('例题',r"f(x)=x^3-3x"),R('结果',r"x=-1:\ f(-1)=2;\qquad x=1:\ f(1)=-2")],[P('局部极值先找候选点，确认函数在该点连续，再看导数在两侧的符号。由正变负是极大值，由负变正是极小值，不变号就不能根据这个候选点认定有极值。函数在候选点也要保持连续；不可导处仍可能有极值，比如绝对值在零处，所以不能只收集导数等于零的点。',[1,2],['正变负极大，负变正极小','候选点不一定真的有极值']),P('继续用刚才的符号表，负一处由正转负，所以极大值是函数值二；一处由负转正，所以极小值是负二。注意题目问极值点时答横坐标或点的坐标，问极值时要把原函数值算出来。把导数值零当成极值，是一种很常见但可以避免的失分。',[3,4],['极值必须代回原函数','分清极值点与极值'])],['极值的第一、第二判别法'])
S(c,'极值第二判别法：先有一阶为零',[T('前提',"f'(a)=0，并且 f''(a) 存在"),R('二阶为正：极小值',"f''(a)>0"),R('二阶为负：极大值',"f''(a)<0"),T('二阶为零时不能直接下结论','x^4 在0处极小；x^3 在0处无极值')],[P('第二判别法适合驻点上二阶导数不为零的情形。先确认一阶导数在这个点等于零，再看二阶：正对应极小，负对应极大。它省去了部分左右验号，但前提不能省略。随便找一个二阶导数大于零的位置，并不能说那个位置就是极小值点，因为它可能还在递增。',[1,2,3],['先有一阶导数为零','二阶正极小，二阶负极大']),P('如果二阶导数等于零，这个方法暂时没有结论，不表示没有极值。x的四次方在零处有极小，而x立方在零处没有极值，两者二阶导数在那里都为零。遇到这种情况就回到第一判别法，检查一阶导数的左右变号。不要为了省一步，把条件不满足误写成结论相反。',[4],['二阶等于零时回到第一判别法','无法判别不等于不存在'])],['极值的第一、第二判别法'])
S(c,'凹凸与拐点：改用二阶导数验号',[R('方向与符号',r"f''(x)>0:\ \cup,\qquad f''(x)<0:\ \cap"),R('例题',r"f(x)=x^3,\quad f''(x)=6x"),R('分段',r"x<0:\ \cap;\qquad x>0:\ \cup"),R('拐点坐标',r"(0,f(0))=(0,0)"),R('不能仅凭二阶为零',r"f(x)=x^4,\quad f''(x)=12x^2\ge0")],[P('凹凸区间把单调题的一阶导数换成二阶导数，再按关键点分段验号。二阶为正画成开口向上的碗形，二阶为负画成开口向下的帽形。不同教材对单独“凹”或“凸”的称呼可能不同，这里直接把方向和符号一起写，考试按本校教材的名称对应，避免只背一个字。',[1,2],['看二阶导数的正负','名称按本校教材，方向与符号明确']),P('x立方的二阶导数是六x，在零两侧变号，曲线也经过零点，所以零、零是拐点。拐点要检查连续并且凹凸方向确实改变，答案通常写坐标。二阶为零或不存在的位置只是候选，x四次方的二阶导数在零两侧都不为负，所以零不是拐点。函数根本没定义的点也不能成为拐点。',[3,4,5],['拐点要连续且凹凸改变','二阶为零只是候选'])],['凹凸区间、拐点'])
S(c,'闭区间最值：候选值全部比较',[R('例题',r"f(x)=x^3-3x,\quad x\in[-2,2]"),R('内部驻点',r"f'(x)=0\quad\Longrightarrow\quad x=-1,1"),R('端点与内部点都代入',r"f(-2)=-2,\ f(-1)=2,\ f(1)=-2,\ f(2)=2"),R('最大最小值',r"M=2,\quad m=-2")],[P('求闭区间最大最小值，不要只在局部极值里挑。连续函数在闭区间能取得最值，计算时把区间内部的驻点、函数有定义的不可导候选点，以及两个端点都列出来，逐个代回原函数，比较数值。端点不一定满足导数为零，却完全可能取得全区间最值。',[1,2],['内部候选点加两个端点','最值比较的是原函数值']),P('例题候选位置是负二、负一、一、二，对应值负二、二、负二、二。因此最大值二，在负一和二处都取到；最小值负二，在负二和一处都取到。题目若要求取得位置，也要完整写出并列的位置。不要因为一个最大值有两个位置，就错误地认为函数没有最大值。',[3,4],['同一个最值可以在多处取得','问取得位置时不要漏并列点'])],['最值'])
S(c,'竖直与水平渐近线',[R('任意一侧无穷即可','\\lim_{x\\to a^-}f(x)=\\pm\\infty;\\quad\\lim_{x\\to a^+}f(x)=\\pm\\infty'),R('对应直线',r"x=a"),R('水平渐近线',r"\lim_{x\to+\infty}f(x)=L\quad\Longrightarrow\quad y=L"),R('例题',r"f(x)=\frac1{x-2}+3:\quad x=2,\quad y=3")],[P('渐近线题先分三个方向检查。有限位置附近如果至少一侧函数趋于正无穷或负无穷，就有竖直渐近线x等于那个位置。分母为零只是可疑点，要先约分或算极限，有限的可去间断并不是竖直渐近线。求水平线则看x趋于正无穷或负无穷，是否得到有限常数。',[1,2,3],['竖直线至少一侧无穷即可','正无穷与负无穷分别检查']),P('例题一除以x减二再加三，在二附近无界，所以竖直线x等于二；向正负无穷远处，分式都趋于零，所以水平线y等于三。最后答的是直线方程，不是只写数字二和三。某一侧没有得到有限极限时，还要另查是否存在斜渐近线，而不是强行报一个水平高度。',[4],['水平线写y等于常数','竖直线写x等于常数'])],['渐近线'])
S(c,'斜渐近线：先求斜率再求截距',[R('模板',r"k=\lim_{x\to\infty}\frac{f(x)}x,\quad b=\lim_{x\to\infty}[f(x)-kx]"),R('要求',r"k,b\in\mathbb R,\quad k\ne0,\qquad y=kx+b"),R('例题与除法',r"\frac{2x^2+1}{x-1}=2x+2+\frac3{x-1}"),R('结果',r"y=2x+2,\qquad x=1")],[P('斜渐近线记两次极限：先算函数除以x，得到有限非零斜率k，再算函数减kx，得到有限截距b，最后写y等于kx加b。两步都要成功，不能只找到一个斜率就漏掉截距。正无穷和负无穷也应分别检查，题目中的两侧结果未必完全相同。',[1,2],['先k后b；两者都要有限','k为零时属于水平线情形']),P('有理分式经常可以用多项式除法更快处理。例题拆成二x加二，加三除以x减一；最后一项在无穷远处趋于零，所以斜线就是y等于二x加二。有限位置还要检查分母为零的点，x等于一是竖直渐近线。一个函数可以同时有竖直线和斜线，不要只答其中一种。',[3,4],['多项式除法可直接读出斜线','有限位置的竖直线另查'])],['渐近线'])
S(c,'导数应用练习',[R('题目',r"f(x)=x^3"),R('问题',r"x=0:\quad f'(0)=0,\quad f''(0)=0")],[P('暂停判断：x立方在零处，一阶导数和二阶导数都等于零。这里是不是极值点，是不是拐点？请分别检查一阶导数和二阶导数在零两侧的符号，不要把“导数为零”同时当作这两个问题的充分条件，答案需要两个独立的判断。',[1,2],['极值查一阶左右符号','拐点查二阶左右符号'])],['极值的第一、第二判别法','凹凸区间、拐点'],kind='question')
S(c,'导数应用练习答案',[R('一阶不变号',r"f'(x)=3x^2>0\quad(x\ne0)"),R('二阶发生变号',r"f''(x)=6x:\quad-\to+"),R('结论位置',r"(0,0)")],[P('零不是极值点，因为一阶导数在两侧都为正，函数经过这里仍然保持递增。零、零却是拐点，因为函数在零处连续，二阶导数从负变正，凹凸方向发生了改变。驻点、极值点、拐点是三种不同判断，做题时各用对应的检查步骤，不要让一个零值代替全部条件。',[1,2,3],['没有极值，但有拐点','两种判别步骤不要混用'])],['极值的第一、第二判别法','凹凸区间、拐点'],kind='answer')
